      'lic.title': 'License — openWCS is AGPL-3.0',
      'lic.eyebrow1': 'License <span class="pill pill-built" data-i18n="lic.pill1">AGPL-3.0</span>',
      'lic.pill1': 'AGPL-3.0',
      'lic.h1': 'Open, and <span class="lime">staying open.</span>',
      'lic.lead1': 'openWCS is licensed under the <strong>GNU Affero General Public License, version 3.0</strong>\n        (AGPL-3.0) — a strong copyleft license. You can run it, study it, change it and share it freely.\n        The one rule: improvements to openWCS stay open for everyone, even when it is offered over a network.',
      'lic.eyebrow2': 'The four freedoms',
      'lic.h2': 'What the license grants you.',
      'lic.p1': 'Like every GNU GPL-family license, the AGPL guarantees four freedoms — to everyone who receives\n          the software, at no cost and without asking permission.',
      'lic.tag1': 'Run',
      'lic.h3': 'Use it for anything',
      'lic.p2': 'Run openWCS for any purpose, including commercially, in as many warehouses and on as many machines as you like. No seat counts, no per-flow fees, no usage caps.',
      'lic.tag2': 'Study',
      'lic.h4': 'Read the source',
      'lic.p3': 'The complete source is public. Inspect exactly how every service behaves, audit it for security, and learn from it — no black boxes between your WMS/ERP and the floor.',
      'lic.tag3': 'Modify',
      'lic.h5': 'Change it to fit',
      'lic.p4': 'Adapt openWCS to your warehouse — add device adapters, change flows, fix bugs. It is yours to shape, and you never need our permission to do it.',
      'lic.tag4': 'Share',
      'lic.h6': 'Pass it on',
      'lic.p5': 'Redistribute openWCS, with or without your changes. When you do, your recipients get the same four freedoms and the same source you started from.',
      'lic.eyebrow3': 'Copyleft &amp; the network clause',
      'lic.h7': 'The part that makes it AGPL.',
      'lic.p6': '"Copyleft" means the freedoms travel with the code: anything you build on openWCS and pass on\n          must itself be AGPL-3.0, with source available. The AGPL adds one thing ordinary GPL does not —\n          it closes the "software-as-a-service" gap.',
      'lic.h8': 'Derivatives stay open (§5)',
      'lic.p7': 'If you distribute openWCS or a modified version, you must license the whole work under AGPL-3.0 and provide the corresponding source. You cannot fold it into a closed-source product.',
      'lic.h9': 'Network use counts (§13)',
      'lic.p8': 'This is the Affero clause. If you run a <em>modified</em> openWCS and let users interact with it over a network, you must offer those users the complete source of your modified version — even though you never "distributed" a copy. Ordinary GPL would not require this.',
      'lic.eyebrow4': 'In practice',
      'lic.h10': 'What you can and must do.',
      'lic.p9': 'For almost every operator, the AGPL is a non-event: you run openWCS to control your own warehouse\n          and never trigger an obligation. The duty only appears if you hand modified openWCS to others —\n          as a download or as a hosted service.',
      'lic.tag5': 'You may',
      'lic.h11': 'Run &amp; modify privately',
      'lic.p10': 'Self-host openWCS, run it commercially to operate your own sites, and make private changes you never share. Using the software to run your business is not "conveying" it — your operational data and processes stay entirely yours.',
      'lic.tag6': 'You must',
      'lic.h12': 'Share changes you serve or ship',
      'lic.p11': 'If you distribute a modified openWCS, or offer a modified openWCS to other users as a network service, make your modified source available to them under AGPL-3.0. Keep copyright and license notices intact. The software comes with no warranty.',
      'lic.eyebrow5': 'Common questions',
      'lic.h13': 'Quick answers.',
      'lic.q1': 'Can I use openWCS commercially?',
      'lic.a1': 'Yes, without paying anyone. Run it in production across your operation. The AGPL restricts how you redistribute the software, not whether you can profit from operating it.',
      'lic.q2': 'Do I have to publish my warehouse data or configuration?',
      'lic.a2': 'No. The license covers source code, not the data you process or the BPMN flows and master data you configure. Your inventory, orders and settings are not "the program."',
      'lic.q3': 'I modified openWCS for internal use only — must I share?',
      'lic.a3': 'No. If those changes never leave your organisation — not distributed, not offered to outside users as a service — there is no obligation to publish them. The §13 duty is triggered by serving or shipping to others.',
      'lic.q4': 'The AGPL does not fit my use case — what then?',
      'lic.a4': 'Talk to us. If copyleft is incompatible with how you need to ship or embed openWCS, reach out via the contact button and we can discuss the options.',
      'lic.eyebrow6': 'The fine print',
      'lic.h14': 'Read the actual license.',
      'lic.p12': 'This page is a plain-language summary to help you understand the AGPL-3.0 — it is not legal advice, and the license text itself always governs. The full, authoritative terms ship in the repository and are published by the Free Software Foundation.',
      'lic.btnFull': 'Read the full AGPL-3.0',
