      'conv.nav3': 'Funktionen',
      'conv.nav4': 'AKL',
      'conv.btn1': 'Doku lesen',
      'cc.title': 'Inventur — openWCS',
      'cc.eyebrow1': 'Funktion · Inventur <span class="pill pill-built">Built</span>',
      'cc.eyebrow2': 'Was gebaut ist',
      'cc.eyebrow3': 'Jetzt vollständig',
      'cc.eyebrow4': 'Auf einen Blick',
      'cc.eyebrow5': 'Gebaut &amp; offen',
      'cc.h1': 'Zählen, <span class="lime">in Betrieb.</span>',
      'cc.lead1': 'Inventur und Bestandszählung halten den erfassten Bestand ehrlich. openWCS führt Zählaufgaben, Blind- und Abweichungszählungen sowie Abgleich vollständig durch — Zähltotes werden automatisch an GTP-Arbeitsplätze geroutet, der Zyklus schließt mit einem StockAdjusted-Event.',
      'cc.h2': 'Zählaufgaben, Blindzählung, Abgleich — alles in Betrieb.',
      'cc.h3': 'Der allgemeine Zähl-Screen, ausgeliefert.',
      'cc.h4': 'Der ganze Zählzyklus, gebaut.',
      'cc.h5': 'Zählung läuft — Open Source.',
      'cc.h6': 'Nach Umfang &amp; Zeitplan zählen',
      'cc.h7': 'Ehrliche Zählungen, immer',
      'cc.h8': 'Blindzählung an der GTP-Konsole',
      'cc.h9': 'Zählaufgaben',
      'cc.h10': 'Blind- &amp; Abweichungszählungen',
      'cc.h11': 'Klären &amp; anpassen',
      'cc.h12': 'Allgemeiner Zähl-Screen',
      'cc.tag1': 'Zählaufgaben',
      'cc.tag2': 'Blind &amp; Abweichung',
      'cc.tag3': 'Stationszählung',
      'cc.tag4': 'Aufgaben',
      'cc.tag5': 'Zählmodi',
      'cc.tag6': 'Abgleich',
      'cc.tag7': 'Zähl-UI',
      'cc.pill1': 'Built',
      'cc.pill2': 'Built',
      'cc.pill3': 'Built',
      'cc.pill4': 'Built',
      'cc.pill5': 'Built',
      'cc.pill6': 'Built',
      'cc.pill7': 'Built',
      'cc.pill8': 'Built',
      'cc.p1': 'Zählaufgaben, Blind- und Abweichungszählungen sowie Abgleich sind vollständig implementiert. Zähltotes werden automatisch von ASRS-, AMR- und AutoStore-Zellen zur aktiven GTP-STOCK_COUNT-Arbeitsstation geroutet.',
      'cc.p2': 'Zählaufgaben adressieren jeden Umfang — Lagerplatz, SKU, Zone oder Lagerblock — mit Blind- oder Abweichungsmodus und ABC-Takt-Planung. Zähltotes werden automatisch zur aktiven GTP-STOCK_COUNT-Arbeitsstation geroutet.',
      'cc.p3': 'Der Blindmodus verbirgt die erwartete Menge — der Bediener gibt ein, was er sieht, nie die Systemzahl. Der Abweichungsmodus markiert Unstimmigkeiten. Zwei übereinstimmende Zählungen bestätigen eine Abweichung und buchen automatisch ein StockAdjusted-Event.',
      'cc.p4': 'Wenn ein Zähltote an einer GTP-STOCK_COUNT-Station ankommt, wechselt die Bediener-Konsole zu einem Blindzähl-Panel. Menge eingeben — keine erwartete Menge angezeigt. Zwei übereinstimmende Zählungen schließen das Tote und buchen das StockAdjusted-Event automatisch.',
      'cc.p5': 'Das letzte Stück ist gelandet: ein eigenständiger Bediener-Screen für Zählungen außerhalb einer GTP-Station. Die Zählfunktion ist jetzt End-to-End gebaut.',
      'cc.p6': 'Geplant: Generieren und Verteilen von Zählaufgaben — nach Lagerplatz, nach Geschwindigkeitsklasse oder zyklisch — aus dem COUNT-Auftrag. Noch nicht implementiert.',
      'cc.p7': 'Geplant: Blindzählungen, die die erwartete Menge verbergen, plus Abweichungszählungen, die nur dort nachzählen, wo der erste Durchgang abwich. Entworfen, noch nicht gebaut.',
      'cc.p8': 'Geplant: Abgleich, der gezählt vs. erfasst vergleicht, innerhalb der Toleranz ein StockAdjusted-Event bucht und den Rest eskaliert. Noch nicht implementiert.',
      'cc.p9': 'Ein eigenständiger Bediener-Screen steuert den ganzen Dienst: Ad-hoc- oder geplante Zählaufgaben anlegen, gezählte Mengen pro Zeile erfassen, Abweichungen prüfen, nachzählen und abgleichen. Der Routing-Status der Zählbehälter wird verfolgt, fehlgeschlagenes AKL-Routing automatisch wiederholt.',
      'cc.p10': 'Der vollständige Zählzyklus ist heute im Repo live, von geplanten Zählaufgaben bis zum eigenständigen Zähl-Screen. Lies ihn, betreibe ihn, ändere ihn.',
      'cc.foot5': 'openWCS — Open-Source Warehouse Control System · AGPL-3.0.',
      'cc.nav1': '← Übersicht',
      'cc.nav2': 'Funktionen',
