      footerLicense: '许可协议',
      'lic.title': '许可协议：openWCS 采用 AGPL-3.0',
      'lic.eyebrow1': '许可协议 <span class="pill pill-built" data-i18n="lic.pill1">AGPL-3.0</span>',
      'lic.pill1': 'AGPL-3.0',
      'lic.h1': '开源，并且<span class="lime">始终保持开源。</span>',
      'lic.lead1': 'openWCS 采用<strong>GNU Affero 通用公共许可证第 3 版</strong>\n        （AGPL-3.0）授权，这是一份严格的著佐权（copyleft）许可证。你可以自由运行、研究、修改和分享它。\n        唯一的规则：对 openWCS 的改进必须始终对所有人保持开源，即便是通过网络提供服务。',
      'lic.eyebrow2': '四大自由',
      'lic.h2': '这份许可证赋予你的权利。',
      'lic.p1': '与所有 GNU GPL 系列许可证一样，AGPL 向每一位获得该\n          软件的人保证四项自由，无需付费，也无需征得许可。',
      'lic.tag1': '运行',
      'lic.h3': '用于任何用途',
      'lic.p2': '你可以将 openWCS 用于任何目的（包括商业用途），部署到任意数量的仓库和设备上。没有座席数限制，没有按流程收费，也没有使用上限。',
      'lic.tag2': '研究',
      'lic.h4': '阅读源代码',
      'lic.p3': '完整源代码全部公开。你可以精确查看每个服务的行为、进行安全审计并从中学习：在你的 WMS/ERP 与现场作业之间，没有任何黑箱。',
      'lic.tag3': '修改',
      'lic.h5': '按需改造',
      'lic.p4': '将 openWCS 改造成适合你仓库的样子：新增设备适配器、调整流程、修复缺陷。它由你自主塑造，无需征得我们的同意。',
      'lic.tag4': '分享',
      'lic.h6': '传递下去',
      'lic.p5': '你可以重新分发 openWCS，无论是否包含你的修改。当你这样做时，接收者将获得与你最初一样的四项自由和源代码。',
      'lic.eyebrow3': '著佐权（Copyleft）与网络条款',
      'lic.h7': '让它成为 AGPL 的那一部分。',
      'lic.p6': '「著佐权（copyleft）」意味着自由会随代码一同流传：任何基于 openWCS 构建并对外传递的成果，\n          都必须同样采用 AGPL-3.0 协议并公开源代码。相比普通 GPL，AGPL 多了一项规定，\n          用来堵上「软件即服务」的漏洞。',
      'lic.h8': '衍生作品必须保持开源（第 5 条）',
      'lic.p7': '如果你分发 openWCS 或其修改版本，必须以 AGPL-3.0 协议许可整个作品，并提供相应的源代码。你不能将其并入闭源产品中。',
      'lic.h9': '网络使用也算数（第 13 条）',
      'lic.p8': '这就是 Affero 条款。如果你运行<em>修改过</em>的 openWCS，并允许用户通过网络与之交互，你必须向这些用户提供你修改版本的完整源代码，即便你从未「分发」过任何副本。普通 GPL 并不要求这一点。',
      'lic.eyebrow4': '实际影响',
      'lic.h10': '你可以做什么，必须做什么。',
      'lic.p9': '对绝大多数运营方来说，AGPL 几乎不会带来任何影响：你运行 openWCS 来管理自己的仓库，\n          不会触发任何义务。只有当你把修改过的 openWCS 交给他人\n          （无论是作为下载还是托管服务）时，义务才会出现。',
      'lic.tag5': '你可以',
      'lic.h11': '私下运行与修改',
      'lic.p10': '你可以自行托管 openWCS，将其用于商业运营自己的场地，并进行从不对外分享的私下修改。使用该软件来运营你的业务并不构成「传递」：你的运营数据和流程始终完全属于你自己。',
      'lic.tag6': '你必须',
      'lic.h12': '公开你对外提供或分发的修改',
      'lic.p11': '如果你分发修改过的 openWCS，或以网络服务的形式向其他用户提供修改过的 openWCS，必须依据 AGPL-3.0 向他们提供你修改后的源代码。请保持版权和许可声明完整。本软件不提供任何担保。',
      'lic.eyebrow5': '常见问题',
      'lic.h13': '快速解答。',
      'lic.q1': '我可以将 openWCS 用于商业用途吗？',
      'lic.a1': '可以，而且无需向任何人付费。你可以在生产环境中于整个运营范围内使用它。AGPL 限制的是你如何重新分发软件，而不是你能否通过运营它来盈利。',
      'lic.q2': '我必须公开我的仓库数据或配置吗？',
      'lic.a2': '不需要。该许可证约束的是源代码，而不是你处理的数据，也不是你配置的 BPMN 流程和主数据。你的库存、订单和设置都不属于「该程序」本身。',
      'lic.q3': '我修改 openWCS 仅供内部使用，必须公开吗？',
      'lic.a3': '不需要。只要这些修改从未离开你的组织（既未分发，也未作为服务向外部用户提供），就没有公开的义务。第 13 条的义务是由向他人提供服务或分发触发的。',
      'lic.q4': '如果 AGPL 不适合我的使用场景怎么办？',
      'lic.a4': '欢迎与我们联系。如果著佐权（copyleft）条款与你需要的分发或嵌入方式不兼容，请通过联系按钮与我们沟通，我们可以一起讨论其他方案。',
      'lic.eyebrow6': '细则说明',
      'lic.h14': '阅读许可证正文。',
      'lic.p12': '本页内容是为帮助你理解 AGPL-3.0 而撰写的通俗摘要，并非法律意见，许可证正文始终具有最终效力。完整、权威的条款随代码仓库发布，也可在自由软件基金会（Free Software Foundation）官网查阅。',
      'lic.btnFull': '阅读完整 AGPL-3.0 协议',
      'lic.btnRepo': '仓库中的 LICENSE 文件',
