      'cc.lead1': '循环盘点与库存盘点让账面库存保持真实可信。openWCS 端到端地运行盘点任务、盲盘与差异复盘，以及对账核销：盘点周转箱会自动路由至 GTP 工作站，整个盘点周期最终以一个 StockAdjusted 事件收尾。',
