      'cc.pill8': '已构建',
      'cc.p1': '盘点任务、盲盘与差异复盘、对账核销均已端到端实现。盘点周转箱会从 ASRS、AMR 和 AutoStore 货格自动路由至当前启用的 GTP STOCK_COUNT 工作站。',
      'cc.p2': '盘点任务可针对任意范围（库位、SKU、库区或存储区块），支持盲盘或差异复盘模式，并按 ABC 分类节奏排期。盘点周转箱会自动路由至当前启用的 GTP STOCK_COUNT 工作站。',
      'cc.p3': '盲盘模式会隐藏系统预期数量：操作员只录入自己看到的实际数量，而非系统数值。差异复盘模式则会标记出不一致之处。两次数量一致的盘点即可确认差异，并自动生成 StockAdjusted 事件。',
      'cc.p4': '当盘点周转箱到达 GTP STOCK_COUNT 工位时，操作员控制台会自动切换为盲盘面板：只需录入所见数量，不显示系统预期数量。两次盘点结果一致即可关闭该周转箱，并自动生成 StockAdjusted 事件。',
      'cc.p5': '最后一块拼图已经落地：一个可在 GTP 工位之外独立使用的操作员盘点界面。至此，盘点功能已实现端到端构建。',
      'cc.p6': '规划中：根据 COUNT 订单按库位、按动销等级或按周期生成并派发盘点任务，尚未实现。',
      'cc.p7': '规划中：隐藏预期数量的盲盘，以及仅对首轮结果不一致之处进行复盘的差异复盘。已完成设计，尚未构建。',
      'cc.p8': '规划中：将盘点结果与账面记录进行比对的对账核销，在容差范围内自动生成 StockAdjusted 事件，超出范围的差异则升级处理。尚未实现。',
      'cc.p9': '一个独立的操作员界面驱动整个服务：创建临时或排期盘点任务、按行录入盘点数量、审核差异、复盘并核销。盘点周转箱的路由状态会被全程跟踪，ASRS 路由失败时会自动重试。',
      'cc.p10': '完整的盘点周期今天就已在代码仓库中上线运行，从排期盘点任务到独立盘点界面一应俱全。欢迎阅读源码、运行体验、按需修改。',
      'cc.foot5': 'openWCS：开源仓库控制系统（Warehouse Control System）· AGPL-3.0。',
      'cc.nav1': '← 概览',
      'cc.nav2': '功能',
      'cc.nav3': '自动化',
      'cc.btn1': '返回功能页',
      'aia.title': 'AI 助手：openWCS',
      'aia.eyebrow1': '功能 · AI 助手',
      'aia.pill1': '已构建',
      'aia.h1': '向你的仓库提问，<span class="lime">用大白话就行。</span>',
      'aia.lead1': '一个内嵌于系统中的 AI 助手，通过调用 WCS 自身的只读 API 回答关于订单、运输任务、库存和搬运单元的问题：完全遵循你的权限、限定在你的仓库范围内，且只依据这些 API 返回的结果作答。你需要自行提供 Anthropic API 密钥，在此之前该功能保持禁用状态。',
      'aia.eyebrow2': '它是什么',
      'aia.h2': '一个基于你实时仓库数据的对话助手。',
      'aia.p1': '一个悬浮聊天窗口，操作员或管理者可在系统的任意页面打开。它在一组固定的只读 WCS 接口上运行 Anthropic Claude 的工具调用循环，因此回答基于你的真实数据，而不是关于仓库的通用常识。',
      'aia.tag1': '只读工具',
      'aia.pill2': '已构建',
      'aia.h3': '只能读取，绝不写入',
      'aia.p2': '该助手只能调用只读接口：订单、按 SKU 查询的库存、收发货与库存看板、搬运单元的运输轨迹、运输任务以及库存冻结信息。它无法更改任何订单、库存数值、运输任务或系统设置。',
      'aia.tag2': '你的权限',
      'aia.pill3': '已构建',
      'aia.h4': '权限范围随提问者而定',
      'aia.p3': '助手发出的每一次调用都携带提问者的身份和仓库范围，因此适用与你自己操作界面时完全相同的权限控制和仓库校验。它绝不会显示你自己本就无法获取的数据。',
      'aia.tag3': '密钥在你手中，掌控权也在你手中',
      'aia.pill4': '已构建',
      'aia.h5': '密钥由你自行提供',
      'aia.p4': '管理员只需在“设置”中粘贴 Anthropic API 密钥、选择模型并启用该功能。密钥只写不读：从不回显、从不发送到浏览器，助手仅通过一条从不对外暴露的服务器内部通道读取该密钥。该功能默认关闭，需你主动开启；它是一项外部的、按量计费的依赖服务。',
      'aia.eyebrow3': '一览',
      'aia.h6': '一个问题是如何被回答的。',
      'aia.eyebrow4': '已构建 & 开源',
      'aia.h7': '向你的仓库提问，开源实现。',
      'aia.p5': '该助手已随代码仓库交付。带上你自己的 Anthropic 密钥，在“设置”中启用，即可开始提问。欢迎阅读源码、运行体验、按需修改。',
      'aia.btn1': '返回功能页',
