      'func.eyebrow5': '开源 &amp; 厂商中立',
      'func.h1': 'openWCS 的一切功能，<span class="lime">如实标注。</span>',
      'func.lead1': '一张总览图，涵盖 openWCS 所支持的全部仓库功能。每张卡片都清楚标明该功能目前是\n        <span class="pill pill-built">已构建</span>，还是仍在\n        <span class="pill pill-roadmap">路线图</span>规划中，让你一眼分清哪些现在就能运行，哪些只是设计完成但尚未实现。',
      'func.h2': '其余一切赖以构建的核心。',
      'func.h3': '让货物真正流动起来的功能。',
