      'hw.tag7': '同一场景',
      'hw.tag8': '零额外基础设施',
      'hw.tag9': 'AMR &amp; AutoStore',
      'hw.tag10': '连续位置追踪',
      'hw.pill1': '已构建',
      'hw.pill2': '已构建',
      'hw.pill3': '已构建',
      'hw.pill4': '已构建',
      'hw.pill5': '已构建',
      'hw.pill6': '已构建',
