      'kpi.eyebrow5': '在最新一轮迭代中实现',
      'kpi.h1': '各项数据，<span class="lime">实时来自现场。</span>',
      'kpi.lead1': '产品内置的报表模块，今天已上线：带预测性误差趋势的扫描质量分析、\n        数字孪生场景上的3D流量与移动热力图、带预测的ASRS密度、\n        库存可用性，以及入库/出库高峰。此外还有实时首页看板、五个专区\n        仪表盘，以及通过邮件和webhook推送的阈值告警。',
      'kpi.status1': '✓ 已实现：报表模块今天已在openWCS界面中上线（物流、ASRS、库存、入库、出库），\n        另有实时首页看板、五个专区仪表盘、SLA核心指标卡、全屏安灯看板、告警系统健康度视图，\n        以及通过邮件和webhook推送的阈值告警。演示模式会为仪表盘和告警预置数据，第一天即可实时展示效果。',
      'kpi.h2': '五个屏幕，由实时计数器驱动。',
      'kpi.h3': '实时计数器入内，五个屏幕出站。',
      'kpi.h4': '此刻，读懂你的仓库。',
      'kpi.h5': '扫描、无读、未知项',
      'kpi.h6': '输送机哪里在高负荷运转',
      'kpi.h7': '密度、历史与预测',
      'kpi.h8': '热点格位、繁忙设备',
      'kpi.h9': '可用、已分配、不可用',
      'kpi.h10': '每日流量，每小时高峰',
      'kpi.h11': '实时仪表盘与主动找上你的告警。',
      'kpi.h12': '从查看数据到即时寻呼',
      'kpi.h13': '状态核心指标与ABC动销分析',
      'kpi.tag1': '扫描质量',
      'kpi.tag2': '流量热力图',
      'kpi.tag3': 'ASRS密度',
      'kpi.tag4': 'ASRS移动',
      'kpi.tag5': '库存',
      'kpi.tag6': '入库与出库',
      'kpi.tag7': '阈值告警',
      'kpi.tag8': '仪表盘菜单',
      'kpi.tag9': '安灯与告警健康度',
      'kpi.h14': '一块墙面看板和一台噪声计',
      'kpi.pill10': '已实现',
      'kpi.p12': '已实现：面向控制室的全屏安灯看板（严重告警优先显示，无未决事项时呈现平静的全部正常画面），\n          以及一个衡量告警负荷本身的告警系统健康度界面（按严重程度划分的活跃告警、每日新开与已清除数量、\n          频繁跳动和陈旧告警），遵循ISA-18.2标准以保持告警的可操作性。开启演示模式，仪表盘和告警会自动填充真实感数据。',
      'kpi.pill1': '已实现',
      'kpi.pill2': '已实现',
      'kpi.pill3': '已实现',
      'kpi.pill4': '已实现',
      'kpi.pill5': '已实现',
      'kpi.pill6': '已实现',
      'kpi.pill7': '已实现',
      'kpi.pill8': '已实现',
      'kpi.pill9': '已实现',
      'kpi.p1': '各服务在数据产生的瞬间即采集数据：逐次扫描计数器和每日密度快照，\n          历史数据从部署当天起持续累积。报表模块将这些数据转化为五个屏幕：\n          物流、ASRS、库存、入库和出库。',
      'kpi.p2': '按扫描点和天数统计的扫描、无读和未知项，外加一张“需关注扫描器”列表，\n          标记出错误率呈上升趋势的设备，让一个正在失效的读码器在拖垮产线之前就被修复。',
      'kpi.p3': '渲染在与数字孪生同一场景上的3D输送机流量热力图，外加按天统计的运输时间p50/p95，\n          让繁忙路段和缓慢的日子一目了然。',
      'kpi.p4': '按区块统计的存储密度（数值与百分比），附带90天每日快照历史，\n          以及以曲线虚线延伸方式绘制的14天工作日季节性预测。',
      'kpi.p5': '3D货位移动热力图展示哪些格位周转频繁、哪些处于沉睡状态，存储移动量按设备拆分，\n          让负载不均一目了然，而非凭猜测判断。',
      'kpi.p6': '按SKU拆分为可用、已分配和不可用的数量，让真正能够承诺的数量不再是猜测。',
      'kpi.p7': '预期、已开始与进行中订单的对比，90天的每日数值，以及一张精确显示高峰出现时刻的24小时日内分布图。',
      'kpi.p8': '报表模块今天已在开源UI中上线。打开在线演示，浏览这五个屏幕，从扫描质量一路看到3D热力图。',
      'kpi.p9': '报表层在真正有价值的地方持续生长：从可查看的数据，成长为实时首页看板、\n          专区仪表盘，以及通过邮件和webhook主动找上你的阈值告警。',
      'kpi.p10': '已实现：一项服务每分钟按可配置阈值评估仪表盘指标，在超限时开出警告和严重告警，\n          在指标恢复后清除告警，并通过邮件和webhook逐条推送。',
      'kpi.p11': '已实现：一个带状态感知核心指标卡的实时首页看板（大号数字、目标进度条和迷你趋势图，\n          仅在需要关注时才会着色），以及五个专区仪表盘（入库、出库、补货、库存，\n          以及带帕累托曲线的ABC动销分析）。出库看板现已加入SLA核心指标（截止前准时率、周期时间）；\n          ABC上升和下降品项对比近14天与90天的数据。阈值可在“设置”中编辑。',
      'kpi.foot5': 'openWCS：开源仓库控制系统 · AGPL-3.0。',
