      'pick.h1': '计划已就绪。<span class="lime">现在由操作员确认拣选。</span>',
      'pick.lead1': 'openWCS负责规划拣选，完整的货到人（GTP）工作站流程已上线，支持三种拣选布局\n        和实体拣选灯（pick-to-light），全部\n        <span class="pill pill-built">已实现</span>。语音引导是唯一尚在规划中的环节。',
      'pick.status1': '✓ 以扫描为先的RF拣选、拣选灯和完整的GTP工作站流程如今全部已建成并上线。\n        语音引导是唯一尚在规划中的环节。',
      'pick.demoLink': '想试试看？在<a href="/live-demo">只读在线演示</a>中的货到人工作站拣选五个料箱（无需登录，不保存任何数据）。',
