      'pick.pill8': '已实现',
      'pick.p1': '在任何人碰到料箱之前，那些关键决策已经完成：锁定哪些库存、如何装入容器，\n          以及如何将订单行归组为高效的工作任务。',
      'pick.p2': '订单被分配到具体库存，同时遵循可用性和库位模型，因此每一行都在工作释放前\n          指向一个真实、可触达的单元。',
      'pick.p3': '订单行会被适配到多种规格的纸箱／料箱中，让规划者在工作落地到现场之前，\n          就知道一批订单需要多少个某种规格的容器。',
      'pick.p4': '批量拣选规划将订单行归组为高效的拣选工作，这是波次／批次拣选的基础，\n          也是执行环节日后据以驱动的规划依据。',
      'pick.p5': '操作员拣选界面、拣选灯和完整的货到人工作站流程\n          全部已建成并上线。语音引导是唯一尚在规划中的环节。',
      'pick.p6': '一个引导式RF风格的拣选界面带领操作员完成整个拣选队列：一张大号的下一件拣选卡片，\n          显示库位、SKU编码、名称和图片以及数量，随后通过“确认”或“缺货”（回车键即确认）推进。\n          每次确认都会提交一条Picked交易并扣减库存；该队列由订单管理的拣选任务接口\n          针对已释放、已分配的出库行提供数据。',
      'pick.p7': '已实现：拣选界面是一款可安装的PWA应用，专为工业级Android手持终端\n          的键盘楔入模式打造。操作员先扫描库位再扫描SKU；扫描错误会发出警告并震动，\n          扫描到全部数量则自动确认。离线确认队列可以扛过一次Wi-Fi中断，\n          让手持终端永远不会丢失工作进度。语音引导是唯一尚在规划中的环节。',
      'pick.p8': '已实现：完整的GTP工作站流程，包括呈现搬运单元、按布局渲染拣选内容\n          （一对一、批次格位或分墙），驱动格口拣选灯，释放载具，\n          全部建立在已经把单元送到工作站的ASRS取货流程之上。',
      'pick.p9': '驱动拣选的这套规划引擎，正是驱动上架规划和ASRS取货的同一个引擎。执行环节的进展公开可见。',
      'pick.foot5': 'openWCS：开源仓库控制系统 · AGPL-3.0。',
