      'arch.svc8h': '翻译官',
      'arch.svc8p': '每种机器类型都有一个小型翻译官，因此各厂商的特殊之处都被限定在一处：新增一个厂商，只需编写一个适配器。',
      'arch.svc9t': '事件日志',
      'arch.svc9h': '共享日志',
      'arch.svc9p': '每一次搬运都被按顺序记录一次，且永远不可编辑，是所有部件都信赖的唯一真相来源。',
      'arch.eyebrow4': '这对你意味着什么',
      'arch.h4': '为什么要这样构建？',
      'arch.p3': '这种"小型专才"式设计不只是工程上的整洁，它改变了你能用这套系统做到的事情。',
      'arch.why1h': '韧性',
      'arch.why1p': '如果某个部件需要重启或升级，其余部件照常运行。没有单一开关能让整个仓库瘫痪。',
      'arch.why2h': '可扩展性',
      'arch.why2p': '需要新机器、新流程或新规则？你只需新增或修改一个小部件，而不必重写一切。业务增长不等于推倒重来。',
      'arch.why3h': '不被供应商锁定',
      'arch.why3p': '设备通过可替换的翻译官进行通信，因此你永远不会被绑定在某个机器品牌或某个集成商的合同上。',
      'arch.why4h': '开源',
      'arch.why4p': '每一行代码都是开放的，归你运行、阅读和修改。你的数据和运营逻辑始终留在你手中，离开时也无需推倒重来。',
      'arch.scaleEye': '随处运行，随你扩展',
      'arch.scaleH': '已就绪于 Kubernetes 与负载均衡器。',
      'arch.scaleLead': '每个服务都是无状态的，因此 openWCS 可以在任意负载均衡器后面按需运行任意多份副本。它自带可直接应用的 Kubernetes 清单，部署之后，就能随你的仓库需求自动伸缩。',
      'arch.scale1h': '按峰值伸缩，而非按平均值配置',
      'arch.scale1p': '无论是数万单量的订单波次，还是满场同时扫描的输送机，都只需为繁忙的服务增加副本，而不必购置更大的机器。容量横向增长，按需而来。',
      'arch.scale2h': '始终在线',
      'arch.scale2p': '每个服务运行多份副本意味着没有单点故障，升级也可以逐份副本滚动进行，因此你可以在班次进行中更新系统而不产生停机。',
      'arch.scale3h': '用多少，付多少',
      'arch.scale3p': '自动伸缩会在流量激增时增加副本，在空闲时移除副本，因此你不会在周日的清闲时段为高峰日的硬件配置买单。',
      'arch.scale4h': '你的云，或你的服务器',
      'arch.scale4p': '标准 Kubernetes 可以运行在任意云上或你自己的数据中心，没有专有平台，没有锁定。同一套开放系统，你可以选择在任何地方运行它。',
