      'arch.h5': '完整的端到端旅程。',
      'arch.p4': '这里从现场的视角讲述同一个故事：一件货品从抵达那一刻到最终登上出库卡车之间发生了什么。每个步骤都由上面提到的某位专家负责。',
      'arch.j1t': '收货。',
      'arch.j1p': '一批货物到达。openWCS 将其与预期收货信息核对，并将新库存记入实时库存。',
      'arch.j2t': '上架与分配库位。',
      'arch.j2p': '分配库位为该单元挑选最佳存放位置（畅销品靠近出口），现场调度员将其派送过去。',
      'arch.j3t': '存储。',
      'arch.j3p': '该单元在自动化存储区等待。系统始终确切知道是哪个库位存放着它。',
      'arch.j4t': '订单到达。',
      'arch.j4p': '你的 WMS/ERP 通过 Host API 发送一个订单。订单服务将其加入待办清单。',
      'arch.j5t': '分配。',
