      'ld.guideLead': '这个沙盒是一个只读快照，大多数界面只能浏览。唯一能真正操作的是拣选工作站，所以从那里开始，再去逛逛带有示例数据的其他菜单。',
      'ld.guideStationTag': '重头戏',
      'ld.guideStationH': '在 PP1 拣选五个周转箱',
      'ld.guideStep1': '在左侧菜单中打开<strong>作业，然后进入 GTP 工作站</strong>，选择<strong>PP1（拣选工作站 1）</strong>。',
      'ld.guideStep2': '认领该工作站。五个周转箱已经完成入站，正排队等在你面前。',
      'ld.guideStep3': '对每个周转箱，先呈现库存，再确认<strong>整拣</strong>，或输入一个更小的数量以完成<strong>欠拣</strong>。',
      'ld.guideStep4': '试试异常情况：把某个周转箱标记为脏污，或上报若干件商品破损，观察流程如何随之调整。',
