      'ld.guideLayouts': '想看其他布局？<strong>PP2</strong> 是一个带亮灯货位的一对多工作站，<strong>PW1</strong> 是带电子标签拣选的分播墙，各自会渲染出对应的货位与灯光状态。',
      'ld.guideDataTag': '值得一看',
      'ld.guideDataH': '带有示例数据的菜单',
      'ld.guideData1': '<strong>概览</strong>（首页）：库存、入库、出库、发运和自动化的实时磁贴。',
      'ld.guideData2': '<strong>仪表盘：</strong>库存水平、ABC 动销分析、补货以及全屏 Andon 看板。',
      'ld.guideData3': '<strong>作业：</strong>库存概览、搬运单元、库存盘点、拣选、运输以及实时的<strong>硬件可视化</strong>。',
      'ld.guideData4': '<strong>报表：</strong>物流流向、ASRS、库存、入库和出库图表。',
      'ld.guideData5': '<strong>主数据：</strong>仓库、SKU、库位、区域、存储区块和搬运单元类型。',
      'ld.guideData6': '<strong>工程：</strong>分配库位、流程设计器和 3D 自动化拓扑图。',
      'ld.guideData7': '<strong>系统管理：</strong>数据库浏览器、用户和仓库访问权限。',
      'ld.guideTwinNote': '不要错过<strong>作业，然后进入硬件可视化</strong>：一个实时的自动化 3D 数字孪生，周转箱沿输送机环线行驶，机器人在通道间穿梭，堆垛机在货架上作业。',
      'ld.guideEmptyNote': '未纳入快照的界面会显示简洁的空状态，而不是报错，所以尽管随意点开任何内容。',
